package org.dpdns.gmm;
import static org.junit.Assert.*;
import android.content.Context;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w640dp-h320dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class NativeRoster60HumanPvpTest {
 final NativeHomePartyFeedbackTest helper=new NativeHomePartyFeedbackTest();
 static final NativeHomePartyFeedbackTest.Profile SMALL=new NativeHomePartyFeedbackTest.Profile("pvp-640x320",640,320,160,1,0,0,0,0);
 @Before public void setup(){helper.isolate();helper.configure(SMALL);} @After public void restore(){helper.restore();}
 static JSONObject battle()throws Exception{JSONObject r=new JSONObject(NativeRoster60ProductBattleTest.view().toString());r.getJSONObject("state").getJSONArray("fighters").getJSONObject(0).put("speciesId","u01");r.getJSONObject("state").getJSONArray("fighters").getJSONObject(1).put("speciesId","u01");r.put("waitingForOpponent",false);r.put("disabledCommands",MainActivity.obj("item","","switch","","escape",""));r.getJSONObject("state").put("reserves",new JSONArray());return r;}
 static class Api extends NativeApi {List<String> paths=new ArrayList<>();List<JSONObject> writes=new ArrayList<>();Result pending;JSONObject current=MainActivity.obj("status","idle");Api(Context c){super(c);}@Override String token(){return "human-pvp-test";}@Override void call(String p,JSONObject b,Result cb){paths.add(p);if(p.equals("native/roster60/story/state")){cb.done(NativeRoster60StoryTest.state(),null);return;}if(p.endsWith("pvp/options")){JSONArray units=new JSONArray(),ids=new JSONArray();for(int i=0;i<7;i++){units.put(MainActivity.obj("ownedId","owned"+i,"speciesId","u01","name","개체"+i,"level",60,"maxLevel",60,"rankEligible",true,"rankReason",""));if(i<6)ids.put("owned"+i);}cb.done(MainActivity.obj("units",units,"partyIds",ids,"rankEligibility",NativePlayNavigationTest.rankEligibility(60,true,"")),null);return;}if(p.endsWith("pvp/current")){cb.done(current,null);return;}if(b!=null)writes.add(b);if(p.endsWith("pvp/party")){cb.done(new JSONObject(),null);return;}pending=cb;}}
 void clear(MainActivity h){h.getSharedPreferences("roster60_human_queue",0).edit().clear().commit();h.getSharedPreferences("roster60_product_battle",0).edit().clear().commit();}
 @Test public void productTeamUsesSixPartyAndHumanMatchTransport()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);h.state.put("tutorial",MainActivity.obj("flow","roster60-v1"));h.openRosterPvp();assertEquals("roster60Pvp",h.screen);assertEquals(6,h.rosterPvp.selected.size());h.rosterPvp.drawParty();h.root.findViewWithTag("party-unit-owned6").performClick();assertEquals(6,h.rosterPvp.selected.size());assertTrue(h.rosterPvp.status.getText().toString().contains("최대 6"));h.rosterPvp.drawParty();h.root.findViewWithTag("party-unit-owned0").performClick();h.rosterPvp.drawParty();h.root.findViewWithTag("party-unit-owned6").performClick();assertEquals(6,h.rosterPvp.selected.size());h.rosterPvp.normal.performClick();assertEquals(6,api.writes.get(0).getJSONArray("ownedIds").length());assertEquals("normal",api.writes.get(1).getString("mode"));h.rosterPvp.normal.performClick();assertEquals(2,api.writes.size());api.current=MainActivity.obj("status","waiting","mode","normal");api.pending.done(api.current,null);assertTrue(h.rosterPvp.waiting);h.back();assertEquals("home",h.screen);assertFalse(api.paths.contains("native/roster60/pvp/cancel"));LocalGameArtTest.drain();h.villageHome.navigate("rank");assertEquals("normal",h.rosterPvp.selectedMode);assertTrue(h.rosterPvp.waiting);h.rosterPvp.cancel.performClick();assertTrue(api.paths.contains("native/roster60/pvp/cancel"));api.pending.done(MainActivity.obj("status","idle"),null);assertFalse(h.rosterPvp.waiting);assertFalse(api.paths.contains("native/team"));h.rosterPvp.pause();}}
 @Test public void acceptanceSixthSkillAndReconnectUseSharedServerState()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);JSONObject accepted=battle();accepted.put("status","ACCEPTING");accepted.put("deadline",System.currentTimeMillis()+10000);h.openRosterHumanBattle(accepted);NativeRoster60PvpBattle ui=(NativeRoster60PvpBattle)h.rosterBattle;ui.accept.performClick();ui.accept.performClick();assertEquals(1,api.writes.size());assertTrue(api.writes.get(0).getBoolean("accept"));JSONObject active=battle();api.pending.done(active,null);NativeRoster60ProductBattleTest.named(ui.panel,"기술").performClick();Button sixth=NativeRoster60ProductBattleTest.named(ui.panel,"시험기술5");long down=android.os.SystemClock.uptimeMillis();NativeRoster60ProductBattleTest.touch(sixth,MotionEvent.ACTION_DOWN,down);NativeRoster60ProductBattleTest.touch(sixth,MotionEvent.ACTION_CANCEL,down);NativeRoster60ProductBattleTest.touch(sixth,MotionEvent.ACTION_UP,down);assertEquals(1,api.writes.size());sixth.performClick();assertEquals("s5",api.writes.get(1).getJSONObject("action").getString("skillId"));JSONObject request=api.writes.get(1);api.pending.done(null,"network");ui.resume();assertEquals(request.toString(),api.writes.get(2).toString());JSONObject waiting=battle();waiting.put("waitingForOpponent",true);api.pending.done(waiting,null);assertTrue(ui.message.getText().toString().contains("상대 선택 대기"));assertTrue(ui.waitingSurrender.isEnabled());helper.layout(h,SMALL);helper.png(NativeHomePartyFeedbackTest.render(h.root),"human-pvp-640x320-robolectric.png");ui.pause();assertFalse(api.paths.contains("native/roster60/battle/action"));}}
 @Test public void forcedSwitchIsManualAndPauseStopsPolling()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);JSONObject r=battle();r.getJSONObject("state").getJSONArray("fighters").getJSONObject(0).put("hp",0);JSONObject reserve=new JSONObject(r.getJSONObject("state").getJSONArray("fighters").getJSONObject(1).toString());reserve.put("ownedId","reserve");r.getJSONObject("state").put("reserves",new JSONArray().put(reserve));h.openRosterHumanBattle(r);NativeRoster60PvpBattle ui=(NativeRoster60PvpBattle)h.rosterBattle;assertTrue(ui.message.getText().toString().contains("강제")||ui.message.getText().toString().contains("전투불가"));assertEquals(0,api.writes.size());NativeRoster60ProductBattleTest.named(ui.panel,"교체").performClick();ui.choicePanel.findViewWithTag("battle-switch-reserve").performClick();assertEquals(0,api.writes.size());ui.choicePanel.findViewWithTag("battle-switch-confirm").performClick();assertEquals(1,api.writes.size());assertEquals("switch",api.writes.get(0).getJSONObject("action").getString("kind"));assertEquals("reserve",api.writes.get(0).getJSONObject("action").getString("targetOwnedId"));api.pending.done(battle(),null);ui.pause();int calls=api.paths.size();org.robolectric.shadows.ShadowLooper.idleMainLooper(3,java.util.concurrent.TimeUnit.SECONDS);assertEquals(calls,api.paths.size());}}

 @Test public void acceptedWaiterReturnsToServerQueueWithoutSettlingExpiredRoom()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);api.current=MainActivity.obj("status","waiting");JSONObject ended=battle();ended.put("status","FINISHED");ended.put("requeued",true);h.openRosterHumanBattle(ended);assertEquals("roster60Pvp",h.screen);assertTrue(h.rosterPvp.waiting);assertEquals(0,api.writes.size());h.rosterPvp.pause();}}

 @Test public void staleRankAdmissionShowsTheServerReasonWithoutJoiningOrChangingToNormal()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);JSONObject ended=battle();ended.put("mode","rank").put("status","SETTLED").put("settlement",MainActivity.obj("xpAwarded",0,"reason","SERVER_ABORT","rankCondition","RANK_QUEUE_CLASS_CHANGED"));h.openRosterHumanBattle(ended);assertEquals("rank",h.rosterPvpMode);assertTrue(h.rosterBattle.message.getText().toString().contains("환생 이력"));assertFalse(h.rosterBattle.message.getText().toString().contains("RANK_"));assertTrue(api.writes.isEmpty());assertFalse(api.paths.contains("native/roster60/pvp/join"));h.rosterBattle.pause();}}

 @Test public void definitiveRankAcceptRejectionClearsItsReceiptAndReadsTheExistingRoomOnly()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);JSONObject accepting=battle();accepting.put("mode","rank").put("status","ACCEPTING").put("deadline",System.currentTimeMillis()+10000);h.openRosterHumanBattle(accepting);NativeRoster60PvpBattle ui=(NativeRoster60PvpBattle)h.rosterBattle;ui.accept.performClick();assertEquals(1,api.writes.size());assertFalse(ui.prefs.getString(ui.key+":pending","").isEmpty());JSONObject ended=battle();ended.put("mode","rank").put("status","SETTLED").put("settlement",MainActivity.obj("xpAwarded",0,"reason","SERVER_ABORT","rankCondition","RANK_CATALOG_CHANGED"));api.current=MainActivity.obj("status","matched","mode","rank","battle",ended);api.pending.done(null,"RANK_CATALOG_CHANGED");assertTrue(ui.prefs.getString(ui.key+":pending","").isEmpty());assertEquals("rank",h.rosterPvpMode);assertTrue(ui.message.getText().toString().contains("랭크 조건"));assertEquals(1,api.writes.size());assertFalse(api.paths.contains("native/roster60/pvp/join"));ui.pause();}}

 @Test public void anOpponentPoolChangeUsesOnlyThePersonalTerminalNotice()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();helper.prepare(h);Api api=new Api(h);h.api=api;clear(h);JSONObject settlement=NativeNormalXpPresentationTest.settlement("TERMINAL_POLICY_PENDING",0,0);settlement.put("reason","SERVER_ABORT").put("matchPoolCondition","MATCH_POOL_OPPONENT_CHANGED");JSONObject ended=battle();ended.put("mode","normal").put("status","SETTLED").put("settlement",settlement);h.openRosterHumanBattle(ended);assertEquals("normal",h.rosterPvpMode);assertTrue(h.rosterBattle.message.getText().toString().contains("상대의 참가 조건"));assertFalse(h.rosterBattle.message.getText().toString().contains("REBORN"));assertFalse(h.rosterBattle.message.getText().toString().contains("FIRST_LIFE"));assertTrue(api.writes.isEmpty());h.rosterBattle.pause();}}

 @Test public void graceLabelsUseServerDeadlinesAndNeverDeclareAClientLossOrXpAmount()throws Exception{JSONObject snapshot=battle();snapshot.put("status","ACTIVE").put("serverNow",1000).put("presence",MainActivity.obj("status","RECONNECT_GRACE","ownGraceUntil",6000,"opponentGraceUntil",9000,"serverNow",1000));String grace=NativeRoster60PvpBattle.presenceText(snapshot);assertTrue(grace.contains("내 연결 5초"));assertTrue(grace.contains("상대 연결 8초"));assertFalse(grace.contains("패배"));assertFalse(grace.contains("경험치"));snapshot.getJSONObject("presence").put("serverNow",10000);assertTrue(NativeRoster60PvpBattle.presenceText(snapshot).contains("결과 확인 중"));assertFalse(NativeRoster60PvpBattle.presenceText(snapshot).contains("패배"));snapshot.put("presence",MainActivity.obj("status","OBSERVATION_UNAVAILABLE"));assertTrue(NativeRoster60PvpBattle.presenceText(snapshot).contains("연결 상태 확인"));assertFalse(NativeRoster60PvpBattle.presenceText(snapshot).contains("연결 종료"));snapshot.put("presence",MainActivity.obj("status","CONNECTED"));assertEquals("",NativeRoster60PvpBattle.presenceText(snapshot));snapshot.put("status","SETTLED").put("presence",MainActivity.obj("status","RECONNECT_GRACE","ownGraceUntil",6000,"serverNow",1000));assertEquals("",NativeRoster60PvpBattle.presenceText(snapshot));}

}
